const SHAPES = {
  simple: { d: SIMPLE, w: 1348.2, h: 235.5 },
  serif: { d: SERIF, w: 1294.2, h: 243.5 },
}

export type LogoStyle = keyof typeof SHAPES
let style: LogoStyle = 'simple'

/** Which wordmark the designs draw (from মিহার তথ্য). */
export function setLogoStyle(s?: string) {
  style = s === 'serif' ? 'serif' : 'simple'
}

/** Width ÷ height of the current wordmark. */
export const logoRatio = () => SHAPES[style].w / SHAPES[style].h

/**
 * The wordmark at (x, y) [top-left], `w` wide, in one colour `c1`.
 * (`_c2` is kept so older calls still read: the real logo is one colour.)
 */
export function logo(x: number, y: number, w: number, c1: string, _c2?: string): string {
  const s = SHAPES[style]
  const k = w / s.w
  return `<g transform="translate(${x} ${y}) scale(${k})"><path fill="${c1}" fill-rule="evenodd" d="${s.d}"/></g>`
}

/** Height the wordmark takes when drawn `w` wide. */
export const logoH = (w: number) => (w * SHAPES[style].h) / SHAPES[style].w

/** The round "M" at (x, y) [top-left], `size` across. */
export function mark(x: number, y: number, size: number, c: string): string {
  const k = size / 235.8
  return `<g transform="translate(${x} ${y}) scale(${k})"><path fill="${c}" fill-rule="evenodd" d="${MARK}"/></g>`
}

/** The wordmark fitted inside a box (centred), whatever the style. */
export function logoIn(x: number, y: number, w: number, h: number, c: string): string {
  const r = logoRatio()
  const lw = Math.min(w, h * r)
  const lh = lw / r
  return logo(x + (w - lw) / 2, y + (h - lh) / 2, lw, c)
}
